using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Racing;
using HarborValeGreybox.Launch;
namespace HarborValeGreybox.Workshop {
public class ChassisPlayerProbe:MonoBehaviour {
 static string folder;List<string> lines=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--chassis-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<args.Length?Path.GetFullPath(args[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"isolated-v5.json");}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var go=new GameObject("Chassis native verification");DontDestroyOnLoad(go);go.AddComponent<ChassisPlayerProbe>();}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Write()=>File.WriteAllLines(Path.Combine(folder,"player-results.txt"),lines);void Log(string text,string stack,LogType kind){if(!failed&&(kind==LogType.Error||kind==LogType.Exception)){failed=true;lines.Add("FAIL runtime error: "+text);Write();Application.Quit(1);}}
 void Check(bool yes,string text){lines.Add((yes?"PASS ":"FAIL ")+text);if(!yes){failed=true;Write();Application.Quit(1);throw new Exception(text);}}
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Native chassis timeout");}
 IEnumerator Wait(Func<bool> ready){while(!ready())yield return null;yield return new WaitForSecondsRealtime(.5f);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.3f);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+180;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);var shop=UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>();var trial=UnityEngine.Object.FindAnyObjectByType<DocksideTrialDirector>();for(int i=0;i<60;i++)trial.Store.Settle(Finish(trial.Definition),out _);Check(shop.Open(),"Finch chassis shop opens through real modal");shop.View.ShowSetup();yield return Capture("Stock_Setup_Locks");shop.Close();Check(shop.Open(),"Parts browser returns after locked setup preview");foreach(var slot in new[]{"differential","suspension","gearing","aero"})for(int stage=1;stage<=3;stage++)Check(shop.Install(slot+"_"+stage),"Paid chassis install "+slot+stage);Check(shop.Car.Body.mass==1072&&shop.Car.Engine.definition.massKg==1072,"Actual rigidbody and dyno definition include 22kg aero kit");Check(shop.Car.differentialBias==4&&shop.Car.downforceCoefficient>.35f,"Physical LSD bias and aero parameters applied");int credits=shop.Credits;var setup=new WorkshopSetup{rideHeightMm=-20,springPercent=110,damperPercent=105,rollPercent=115,diffLockPercent=80,finalDrivePercent=115,gear1Percent=105,wingPercent=85};Check(shop.SaveSetup(setup)&&shop.Credits==credits,"Parked adjustment persists without charge");Check(Mathf.Abs(shop.Car.Wheels[0].transform.localPosition.y-.435f)<.0001f&&Mathf.Abs(shop.Car.Wheels[0].suspensionSpring.spring-41800)<1,"Ride height and spring adjustment reach real wheel suspension");Check(shop.Car.Engine.definition.finalDrive>shop.Catalog.car.stock.finalDrive,"Final drive actually changes gearing");shop.SelectedId="aero_3";yield return Capture("Dyno_HP_WHP_Weight");shop.View.ShowSetup();Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return Capture("Chassis_Setup_1280x720");Screen.SetResolution(1600,900,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return Capture("Chassis_Setup_1600x900");
  var c=shop.Catalog;foreach(var o in c.MissingPath(shop.Build,c.Find("induction_roots_3")))Check(shop.Install(o.id),"High-power launch hardware "+o.id);shop.Close();shop.Car.externalInput=true;shop.Car.commandedHandbrake=false;shop.Car.commandedPedal=1;shop.Car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(2);Check(shop.Car.IsBrakeBoosting&&Mathf.Abs(shop.Car.Engine.Rpm-shop.Car.Engine.StagingTargetRpm)<100&&shop.Car.SpeedKph<1,"Brake plus accelerator holds tune-specific RPM without rolling");yield return Capture("Brake_Boost_Staged");shop.Car.commandedServiceBrake=0;bool smoke=false;double until=Time.realtimeSinceStartupAsDouble+6;while(Time.realtimeSinceStartupAsDouble<until){if(shop.Car.IsBurningOut&&shop.Car.GetComponent<BurnoutEffects>().ActiveEmitters>0){smoke=true;var chase=shop.Car.GetComponent<HarborValeGreybox.Driving.FinchDrivingHUD>().chase;chase.enabled=false;var cam=Camera.main;cam.transform.position=shop.Car.transform.position+shop.Car.transform.right*4+shop.Car.transform.forward*.5f+Vector3.up*1.25f;cam.transform.LookAt(shop.Car.transform.position+shop.Car.transform.forward*.6f+Vector3.up*.35f);yield return new WaitForSecondsRealtime(.35f);Check(shop.Car.GetComponentsInChildren<ParticleSystem>().Sum(ps=>ps.particleCount)>0,"Smoke contains actual emitted particles");yield return Capture("Actual_Launch_Burnout");chase.enabled=true;break;}yield return null;}Check(smoke,"Actual loaded launch produces driven-tire smoke from measured slip");Check(shop.Car.GetComponentsInChildren<WheelCollider>().Length==4,"Effects do not duplicate wheel physics");shop.Car.commandedPedal=0;shop.Car.Recover();shop.Car.externalInput=false;string paid=File.ReadAllText(trial.Store.PathName);HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene);yield return Wait(()=>!HarborValeLaunch.Instance.Busy);HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>();Check(shop.IsTest&&shop.Build.aeroStage==0,"Apex visit starts stock with no career account");Check(shop.Open(),"Same chassis UI available in Apex");foreach(var slot in new[]{"differential","suspension","gearing","aero"})for(int stage=1;stage<=3;stage++)Check(shop.Install(slot+"_"+stage),"Free chassis install "+slot+stage);Check(shop.SaveSetup(setup),"Apex adjustment free and temporary");Check(shop.Car.Body.mass==1272&&shop.Car.frontDriveShare==.45f,"Apex retains AWD identity and actual aero mass");shop.Close();Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid,"Apex chassis testing cannot change paid Finch ledger");HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=UnityEngine.Object.FindAnyObjectByType<ExpandedWorkshop>();Check(shop.Build.aeroStage==3&&shop.Build.setup.rideHeightMm==-20&&shop.Build.setup.finalDrivePercent==115,"Finch hardware and adjusted setup reload after roundtrip");Check(!failed,"No native runtime errors");Write();Application.Quit(0);
 }
}
}
